<template>
  <AppShell>
    <div class="mb-8"><p class="mb-3 text-sm font-semibold text-brand">YOUR PROFILE</p><h1 class="text-4xl font-black md:text-6xl">个人信息</h1><p class="mt-4 text-lg muted">管理你的账号资料，让企业更了解你。</p></div>
    <div class="grid gap-6 lg:grid-cols-[.72fr_1.28fr]"><section class="card rounded-3xl p-8"><div class="flex flex-col items-center text-center"><div class="profile-avatar">{{ user.userInfo?.nickname?.slice(0, 1) || user.userInfo?.username?.slice(0, 1) || '芽' }}</div><h2 class="mt-5 text-2xl font-black">{{ user.userInfo?.nickname || user.userInfo?.username }}</h2><p class="mt-2 text-sm muted">{{ roleLabel }}</p><span class="mt-5 rounded-full px-4 py-2 text-xs font-bold text-brand" style="background:color-mix(in srgb,var(--brand) 10%,transparent)">已认证账号</span></div><div class="divider my-8"></div><div class="space-y-5 text-sm"><div class="profile-line"><span>用户名</span><b>{{ user.userInfo?.username || '—' }}</b></div><div class="profile-line"><span>注册身份</span><b>{{ roleLabel }}</b></div><div class="profile-line"><span>账号状态</span><b class="text-emerald-500">正常</b></div></div></section><section class="card rounded-3xl p-8"><div class="mb-8"><h2 class="text-2xl font-black">编辑资料</h2><p class="mt-2 text-sm muted">更新展示给招聘方的基本信息。</p></div><el-form :model="form" label-position="top" @submit.prevent="save"><div class="grid gap-x-5 md:grid-cols-2"><el-form-item label="昵称"><el-input v-model="form.nickname" size="large" /></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email" size="large" /></el-form-item><el-form-item label="手机号"><el-input v-model="form.phone" size="large" /></el-form-item><el-form-item label="头像地址"><el-input v-model="form.avatar" size="large" placeholder="可填写图片 URL" /></el-form-item></div><el-form-item label="个人签名"><el-input v-model="form.bio" type="textarea" :rows="4" placeholder="写一句你的职业宣言" /></el-form-item><div class="flex justify-end"><button class="btn-brand rounded-2xl px-6 py-3 text-sm font-bold" @click="save">保存修改</button></div></el-form></section></div>
  </AppShell>
</template>
<script setup>
import { computed, reactive } from 'vue'; import { ElNotification } from 'element-plus'; import AppShell from '../../components/AppShell.vue'; import { useUserStore } from '../../stores/user'
const user = useUserStore(); const roleLabel = computed(() => ({ STUDENT: '学生', COMPANY: '招聘方', ADMIN: '管理员' }[user.role] || '平台用户')); const form = reactive({ nickname: user.userInfo?.nickname || '', email: user.userInfo?.email || '', phone: user.userInfo?.phone || '', avatar: user.userInfo?.avatar || '', bio: '' })
function save() { user.setSession(user.token, { ...user.userInfo, ...form }); ElNotification({ title: '保存成功', message: '个人信息已更新', type: 'success' }) }
</script>
